// figure.js (builder A): the faceless sculpted soloist. API documented in CONTRACT.md (Figure API).
// Geometry comes from src/assets/body-data.js (generated by tools/build-body.mjs): a quantized skinned mesh bound to
// buildSkeleton(THREE) plus 44 helper bones (fractional shoulder/elbow/hip/knee/finger rotations, forearm twist
// distribution, a hip-flexion glute corrective) driven here every frame. The engine only ever touches the 57 bones.
// Dancewear (shorts + tank top) is a material zone evaluated from the rest position, so it skins with the body.
import { BONES, BONE_INDEX, buildSkeleton } from './skeleton.js';
import { BODY_META, BODY_B64 } from './assets/body-data.js';

const MAX_GLOW = 8;
const GLOW_TONE = { charcoal: 0.78, plaster: 0.3, graphite: 0.72 }; // light-grey luminous spot strength per skin
const MATERIALS = {
  charcoal: { color: 0x29292c, roughness: 0.62, metalness: 0.0, sheen: 0.16, sheenRoughness: 0.55, sheenColor: 0x606066, specularIntensity: 0.5, grain: 1.0, cavity: 0.7, glow: 0.45, fabric: 0x141416, fabricRough: 0.9, fabricSheen: 0x34343a },
  plaster: { color: 0xe6e1d7, roughness: 0.93, metalness: 0.0, sheen: 0.12, sheenRoughness: 0.8, sheenColor: 0xffffff, specularIntensity: 0.22, grain: 0.55, cavity: 0.55, glow: 0.3, fabric: 0x8e8c88, fabricRough: 0.93, fabricSheen: 0x9a9a9a },
  graphite: { color: 0x232427, roughness: 0.36, metalness: 0.4, sheen: 0.22, sheenRoughness: 0.4, sheenColor: 0xa0a0a8, specularIntensity: 0.85, grain: 0.45, cavity: 0.6, glow: 0.55, fabric: 0x111113, fabricRough: 0.9, fabricSheen: 0x2e2e34 },
};

// ------------------------------------------------------------------ geometry (decoded once, shared by all figures)
let GEO = null, GEO_REFS = 0;
function decodeGeometry(THREE) {
  const M = BODY_META, s = atob(BODY_B64), bytes = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i);
  const buf = bytes.buffer, L = M.layout, n = M.vertexCount;
  const qp = new Int16Array(buf, L.pos[0], n * 3), on = new Int8Array(buf, L.nrm[0], n * 2);
  const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3);
  for (let i = 0; i < n * 3; i++) { const k = i % 3; pos[i] = M.center[k] + (qp[i] / 32767) * M.halfRange[k]; }
  for (let i = 0; i < n; i++) {
    let x = on[2 * i] / 127, y = on[2 * i + 1] / 127; const z = 1 - Math.abs(x) - Math.abs(y);
    if (z < 0) { const ox = x; x = (1 - Math.abs(y)) * (ox >= 0 ? 1 : -1); y = (1 - Math.abs(ox)) * (y >= 0 ? 1 : -1); }
    const l = Math.hypot(x, y, z) || 1; nrm[3 * i] = x / l; nrm[3 * i + 1] = y / l; nrm[3 * i + 2] = z / l;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
  g.setAttribute('skinIndex', new THREE.BufferAttribute(new Uint8Array(buf, L.skinIndex[0], n * 4), 4));
  g.setAttribute('skinWeight', new THREE.BufferAttribute(new Uint8Array(buf, L.skinWeight[0], n * 4), 4, true));
  g.setAttribute('flesh', new THREE.BufferAttribute(new Uint8Array(buf, L.flesh[0], n), 1, true));
  g.setAttribute('cavity', new THREE.BufferAttribute(new Uint8Array(buf, L.cavity[0], n), 1, true));
  const cn = new Float32Array(n * 3);
  if (L.clothNrm) {
    const oc = new Int8Array(buf, L.clothNrm[0], n * 2);
    for (let i = 0; i < n; i++) {
      let x = oc[2 * i] / 127, y = oc[2 * i + 1] / 127; const z = 1 - Math.abs(x) - Math.abs(y);
      if (z < 0) { const ox = x; x = (1 - Math.abs(y)) * (ox >= 0 ? 1 : -1); y = (1 - Math.abs(ox)) * (y >= 0 ? 1 : -1); }
      const l = Math.hypot(x, y, z) || 1; cn[3 * i] = x / l; cn[3 * i + 1] = y / l; cn[3 * i + 2] = z / l;
    }
  } else cn.set(nrm);
  g.setAttribute('clothNormal', new THREE.BufferAttribute(cn, 3));
  g.setAttribute('clothMask', L.clothMask ? new THREE.BufferAttribute(new Uint8Array(buf, L.clothMask[0], n), 1, true) : new THREE.BufferAttribute(new Uint8Array(n), 1, true));
  const ni = L.index[1] / (M.indexType === 'uint32' ? 4 : 2);
  g.setIndex(new THREE.BufferAttribute(M.indexType === 'uint32' ? new Uint32Array(buf, L.index[0], ni) : new Uint16Array(buf, L.index[0], ni), 1));
  for (const gr of M.groups) g.addGroup(gr.start, gr.count, gr.materialIndex);
  g.computeBoundingBox(); g.computeBoundingSphere();
  return g;
}

// ------------------------------------------------------------------ shader pieces
const NB = BODY_META.bones.length;
const NF = BODY_META.fleshBones || NB; // bones [0, NF) carry flesh offsets; finger joint helpers do not
const GM = BODY_META.garment || { shorts: { waistFront: -9, waistBack: -9, hem: 9, hemRise: 0 }, top: { hem: 9, neckFront: [0, 0], neckBack: [0, 0], armTop: 1, armBottom: 0, armX: 0, armFlare: 0 } };
const f4 = x => (+x).toFixed(4);
const GARMENT_GLSL = /* glsl */`
float gShortsS( vec3 p ) {
  float waist = mix( ${f4(GM.shorts.waistBack)}, ${f4(GM.shorts.waistFront)}, smoothstep( -0.03, 0.03, p.z ) );
  float hem = ${f4(GM.shorts.hem)} + ${f4(GM.shorts.hemRise)} * smoothstep( 0.08, 0.17, abs( p.x ) );
  return min( waist - p.y, p.y - hem );
}
float gTopS( vec3 p ) {
  float ax = abs( p.x ), fr = smoothstep( -0.03, 0.03, p.z );
  float yb = mix( ${f4(GM.top.neckBack[0])}, ${f4(GM.top.neckFront[0])}, fr ), c = mix( ${f4(GM.top.neckBack[1])}, ${f4(GM.top.neckFront[1])}, fr );
  float t = clamp( ( p.y - ${f4(GM.top.armBottom)} ) / ${f4(GM.top.armTop - GM.top.armBottom)}, 0.0, 1.0 );
  float armX = mix( ${f4(GM.top.armXBack ?? GM.top.armX)}, ${f4(GM.top.armX)}, fr );
  return min( min( yb + c * ax * ax - p.y, armX + ${f4(GM.top.armFlare)} * ( 1.0 - sqrt( t ) ) - ax ), p.y - ${f4(GM.top.hem)} );
}
`;
// loose-fit offset along smoothed normals: fabric bridges the navel, cleft and creases; leg hems flare a little
const VERT_CLOTH = /* glsl */`
{
  float cS = gShortsS( position ), cT = gTopS( position );
  float cz = clothOn * clothMask * max( smoothstep( -0.006, 0.01, cS ), smoothstep( -0.006, 0.01, cT ) );
  float cOff = cz * ( 0.0024 + 0.0026 * smoothstep( -0.01, 0.02, cS ) + 0.006 * ( 1.0 - cavity ) );
  cOff += cz * 0.0065 * ( 1.0 - smoothstep( 0.0, 0.09, cS ) ) * smoothstep( 0.87, 0.80, position.y );
  transformed += normalize( mix( normal, clothNormal, cz ) ) * cOff;
}
`;
const VERT_HEAD = /* glsl */`
attribute float clothMask;
attribute vec3 clothNormal;
uniform float clothOn;
varying float vClothMask;
${GARMENT_GLSL}
attribute float flesh;
attribute float cavity;
uniform vec3 fleshOffsets[${NF}];
varying vec3 vRestPos;
varying vec3 vWorldPosG;
varying float vCavity;
`;
const VERT_FLESH = /* glsl */`
#ifdef USE_SKINNING
  if ( flesh > 0.0 ) {
    ivec4 fi = ivec4( skinIndex );
    vec3 fo = vec3( 0.0 );
    if ( fi.x < ${NF} ) fo += fleshOffsets[ fi.x ] * skinWeight.x;
    if ( fi.y < ${NF} ) fo += fleshOffsets[ fi.y ] * skinWeight.y;
    if ( fi.z < ${NF} ) fo += fleshOffsets[ fi.z ] * skinWeight.z;
    if ( fi.w < ${NF} ) fo += fleshOffsets[ fi.w ] * skinWeight.w;
    transformed += flesh * fo;
  }
#endif
`;
const FRAG_HEAD = /* glsl */`
uniform vec4 glowPos[${MAX_GLOW}];
uniform vec4 glowIn[${MAX_GLOW}];
uniform vec3 glowNrm[${MAX_GLOW}];
uniform float clothOn;
uniform vec3 fabricColor;
uniform vec3 fabricSheen;
uniform float fabricRough;
varying float vClothMask;
${GARMENT_GLSL}
uniform float glowInt[${MAX_GLOW}];
uniform int glowCount;
uniform vec3 glowColor;
uniform float grainAmp;
uniform float cavityStrength;
varying vec3 vRestPos;
varying vec3 vWorldPosG;
varying float vCavity;
float gHash( vec3 p ) { p = fract( p * 0.1031 ); p += dot( p, p.zyx + 31.32 ); return fract( ( p.x + p.y ) * p.z ); }
float gNoise( vec3 p ) {
  vec3 i = floor( p ), f = fract( p ); vec3 u = f * f * ( 3.0 - 2.0 * f );
  return mix( mix( mix( gHash( i ), gHash( i + vec3( 1, 0, 0 ) ), u.x ), mix( gHash( i + vec3( 0, 1, 0 ) ), gHash( i + vec3( 1, 1, 0 ) ), u.x ), u.y ),
              mix( mix( gHash( i + vec3( 0, 0, 1 ) ), gHash( i + vec3( 1, 0, 1 ) ), u.x ), mix( gHash( i + vec3( 0, 1, 1 ) ), gHash( i + vec3( 1, 1, 1 ) ), u.x ), u.y ), u.z );
}
float grainHeight( vec3 p, float fw ) {
  float h = 0.00032 * ( gNoise( p * 26.0 ) - 0.5 ) + 0.00014 * ( gNoise( p * 71.0 + 7.1 ) - 0.5 );
  h += 0.00007 * ( gNoise( p * 340.0 + 3.3 ) - 0.5 ) * ( 1.0 - smoothstep( 0.0012, 0.0045, fw ) );
  h += 0.000024 * ( gNoise( p * 1250.0 + 1.7 ) - 0.5 ) * ( 1.0 - smoothstep( 0.00035, 0.0012, fw ) );
  return h * grainAmp;
}
float knitHeight( vec3 p, float fw ) {
  float fade = 1.0 - smoothstep( 0.0006, 0.0018, fw );
  float wale = gNoise( vec3( p.x * 1500.0, p.y * 420.0, p.z * 1500.0 ) ), fine = gNoise( p * 2800.0 + 5.1 );
  return ( 0.00005 * ( wale - 0.5 ) + 0.00002 * ( fine - 0.5 ) ) * fade + 0.00028 * ( gNoise( p * 34.0 + 9.0 ) - 0.5 ) + 0.0001 * ( gNoise( p * 90.0 + 2.0 ) - 0.5 );
}
`;
// per-fragment garment zone: crisp antialiased hems, a hem lip and a stitch line
const FRAG_CLOTH_ZONE = /* glsl */`
float cS = gShortsS( vRestPos ), cT = gTopS( vRestPos );
float cMask = clothOn * smoothstep( 0.5, 0.95, vClothMask );
float cUnderTop = smoothstep( -0.004, 0.004, cT );
float fab = cMask * max( clamp( cS / max( fwidth( cS ), 1e-5 ) + 0.5, 0.0, 1.0 ), clamp( cT / max( fwidth( cT ), 1e-5 ) + 0.5, 0.0, 1.0 ) );
float hemH = cMask * ( 0.0011 * smoothstep( -0.0012, 0.0012, max( cS, cT ) )
  + 0.0008 * exp( - pow( ( cT - 0.0045 ) / 0.0028, 2.0 ) ) + 0.0008 * exp( - pow( ( cS - 0.0045 ) / 0.0028, 2.0 ) ) * ( 1.0 - cUnderTop ) );
float seamFade = 1.0 - smoothstep( 0.0004, 0.0012, length( fwidth( vRestPos ) ) );
float seam = cMask * seamFade * ( exp( - pow( ( cT - 0.009 ) / 0.0008, 2.0 ) ) + exp( - pow( ( cS - 0.009 ) / 0.0008, 2.0 ) ) * ( 1.0 - cUnderTop ) );
`;
const FRAG_NORMAL = /* glsl */`
{
  float gfw = length( fwidth( vRestPos ) );
  float gh = mix( grainHeight( vRestPos, gfw ), knitHeight( vRestPos, gfw ), fab ) + hemH;
  vec2 dH = vec2( dFdx( gh ), dFdy( gh ) );
  vec3 dpx = dFdx( - vViewPosition ), dpy = dFdy( - vViewPosition );
  vec3 r1 = cross( dpy, normal ), r2 = cross( normal, dpx );
  float det = dot( dpx, r1 ) * faceDirection;
  vec3 grad = sign( det ) * ( dH.x * r1 + dH.y * r2 );
  vec3 nn = abs( det ) * normal - grad;
  if ( dot( nn, nn ) > 1e-20 ) normal = normalize( nn );
}
`;
const FRAG_EMISSIVE = /* glsl */`
{
  float gsum = 0.0;
  for ( int i = 0; i < ${MAX_GLOW}; i ++ ) {
    if ( i >= glowCount ) break;
    float r = max( glowPos[ i ].w, 1e-3 );
    vec3 ds = vWorldPosG - glowPos[ i ].xyz; float d2 = dot( ds, ds );
    float spot = exp( - d2 / ( 0.8 * r * r ) ) + 0.24 * exp( - d2 / ( 3.5 * r * r ) );
    // keep the spot on the patch of skin that faces the same way as the anchor (a cap on the head, not a wash)
    vec3 an = normalize( ( viewMatrix * vec4( glowNrm[ i ], 0.0 ) ).xyz );
    gsum += glowInt[ i ] * spot * smoothstep( 0.2, 0.85, dot( normal, an ) );
  }
  float facing = clamp( dot( normalize( vViewPosition ), normal ), 0.0, 1.0 );
  totalEmissiveRadiance += glowColor * ( 1.0 - exp( - 1.5 * gsum ) ) * ( 0.65 + 0.35 * facing );
}
`;
const FRAG_CAVITY = /* glsl */`
{
  float cav = mix( 1.0, vCavity, cavityStrength * ( 1.0 - 0.6 * fab ) );
  reflectedLight.indirectDiffuse *= cav;
  reflectedLight.indirectSpecular *= mix( 1.0, cav, 0.75 );
  reflectedLight.directDiffuse *= mix( 1.0, cav, 0.3 );
}
`;

function patchSurface(shader, U) {
  Object.assign(shader.uniforms, { fleshOffsets: U.fleshOffsets, glowPos: U.glowPos, glowIn: U.glowIn, glowNrm: U.glowNrm, glowInt: U.glowInt, glowCount: U.glowCount, glowColor: U.glowColor, grainAmp: U.grainAmp, cavityStrength: U.cavityStrength,
    clothOn: U.clothOn, fabricColor: U.fabricColor, fabricSheen: U.fabricSheen, fabricRough: U.fabricRough });
  shader.vertexShader = VERT_HEAD + shader.vertexShader
    .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\nobjectNormal = normalize( mix( objectNormal, clothNormal, clothOn * clothMask * max( smoothstep( -0.006, 0.01, gShortsS( position ) ), smoothstep( -0.006, 0.01, gTopS( position ) ) ) ) );')
    .replace('#include <begin_vertex>', '#include <begin_vertex>\n' + VERT_CLOTH)
    .replace('#include <skinning_vertex>', '#include <skinning_vertex>\n' + VERT_FLESH + '\nvRestPos = position;\nvCavity = cavity;\nvClothMask = clothMask;\nvWorldPosG = ( modelMatrix * vec4( transformed, 1.0 ) ).xyz;');
  shader.fragmentShader = FRAG_HEAD + shader.fragmentShader
    .replace('#include <clipping_planes_fragment>', '#include <clipping_planes_fragment>\n' + FRAG_CLOTH_ZONE)
    .replace('#include <color_fragment>', '#include <color_fragment>\ndiffuseColor.rgb = mix( diffuseColor.rgb, fabricColor, fab ) * ( 1.0 - 0.22 * seam );')
    .replace('#include <roughnessmap_fragment>', '#include <roughnessmap_fragment>\nroughnessFactor = mix( roughnessFactor, fabricRough, fab );')
    .replace('#include <metalnessmap_fragment>', '#include <metalnessmap_fragment>\nmetalnessFactor *= 1.0 - fab;')
    .replace('#include <lights_physical_fragment>', '#include <lights_physical_fragment>\n#ifdef USE_SHEEN\nmaterial.sheenColor = mix( material.sheenColor, fabricSheen, fab );\nmaterial.sheenRoughness = mix( material.sheenRoughness, 0.7, fab );\n#endif\nmaterial.specularColor *= mix( 1.0, 0.45, fab );')
    .replace('#include <normal_fragment_maps>', '#include <normal_fragment_maps>\n' + FRAG_NORMAL)
    .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\n' + FRAG_EMISSIVE)
    .replace('#include <aomap_fragment>', '#include <aomap_fragment>\n' + FRAG_CAVITY);
}
function patchDepth(shader, U) {
  shader.uniforms.fleshOffsets = U.fleshOffsets; shader.uniforms.clothOn = U.clothOn;
  shader.vertexShader = `attribute float flesh;\nattribute float cavity;\nattribute float clothMask;\nattribute vec3 clothNormal;\nuniform float clothOn;\nuniform vec3 fleshOffsets[${NF}];\n${GARMENT_GLSL}\n` + shader.vertexShader
    .replace('#include <begin_vertex>', '#include <begin_vertex>\n' + VERT_CLOTH)
    .replace('#include <skinning_vertex>', '#include <skinning_vertex>\n' + VERT_FLESH);
}

function makeMaterialSet(THREE, name, U) {
  const d = MATERIALS[name];
  const make = () => {
    const m = new THREE.MeshPhysicalMaterial({
      color: d.color, roughness: d.roughness, metalness: d.metalness, sheen: d.sheen, sheenRoughness: d.sheenRoughness,
      sheenColor: new THREE.Color(d.sheenColor), specularIntensity: d.specularIntensity,
    });
    m.onBeforeCompile = sh => patchSurface(sh, U);
    m.customProgramCacheKey = () => 'gaga-figure-surface';
    return m;
  };
  return { name, def: d, body: make(), head: make() };
}

// ------------------------------------------------------------------ glow anchors (shared, rest pose)
const ANCHORS = new Map();
function glowAnchor(boneName, o) {
  const key = boneName + '|' + Math.round(o[0] * 500) + ',' + Math.round(o[1] * 500) + ',' + Math.round(o[2] * 500);
  let a = ANCHORS.get(key); if (a) return a;
  const h = BONES[BONE_INDEX[boneName]].head, px = h[0] + o[0], py = h[1] + o[1], pz = h[2] + o[2];
  const P = GEO.attributes.position.array; let best = Infinity, bi = 0;
  for (let i = 0; i < P.length; i += 6) { const dx = P[i] - px, dy = P[i + 1] - py, dz = P[i + 2] - pz, d = dx * dx + dy * dy + dz * dz; if (d < best) { best = d; bi = i; } }
  const N = GEO.attributes.normal.array;
  a = { offset: [P[bi] - h[0], P[bi + 1] - h[1], P[bi + 2] - h[2]], depth: Math.sqrt(best), normal: [N[bi], N[bi + 1], N[bi + 2]] };
  if (ANCHORS.size > 2048) ANCHORS.clear();
  ANCHORS.set(key, a); return a;
}

// ------------------------------------------------------------------ figure
export async function createFigure(THREE, { material = 'charcoal', role = 'soloist' } = {}) {
  if (!GEO) GEO = decodeGeometry(THREE);
  GEO_REFS++;
  const { bones, byName, root } = buildSkeleton(THREE);
  const object3d = new THREE.Group(); object3d.name = 'figure-' + role;
  object3d.add(root);
  // helper bones: children of the source bone's parent, at the source joint
  const helpers = BODY_META.helpers.map(h => {
    const b = new THREE.Bone(); b.name = h.name;
    const src = byName[h.source]; b.position.copy(src.position); byName[h.parent].add(b);
    const dir = BONES[BONE_INDEX[h.source]].dir;
    return { bone: b, src, def: h, axis: new THREE.Vector3(dir[0], dir[1], dir[2]) };
  });
  const allBones = BODY_META.bones.map((n, i) => (i < bones.length ? bones[i] : helpers[i - bones.length].bone));
  object3d.updateMatrixWorld(true);
  const skeleton = new THREE.Skeleton(allBones);

  // per-figure uniforms shared by every material variant of this figure
  const U = {
    fleshOffsets: { value: Array.from({ length: NF }, () => new THREE.Vector3()) },
    glowPos: { value: Array.from({ length: MAX_GLOW }, () => new THREE.Vector4()) },
    glowIn: { value: Array.from({ length: MAX_GLOW }, () => new THREE.Vector4()) },
    glowNrm: { value: Array.from({ length: MAX_GLOW }, () => new THREE.Vector3(0, 0, 1)) },
    glowInt: { value: new Array(MAX_GLOW).fill(0) },
    clothOn: { value: 1 },
    fabricColor: { value: new THREE.Color() },
    fabricSheen: { value: new THREE.Color() },
    fabricRough: { value: 0.9 },
    glowCount: { value: 0 },
    glowColor: { value: new THREE.Color(1.0, 0.86, 0.66) },
    grainAmp: { value: 1 },
    cavityStrength: { value: 0.7 },
  };
  const sets = {};
  const getSet = n => (sets[n] ||= makeMaterialSet(THREE, n, U));
  let current = getSet(MATERIALS[material] ? material : 'charcoal');
  let headVisible = true;

  const mesh = new THREE.SkinnedMesh(GEO, [current.body, current.head]);
  mesh.name = 'figure-body'; mesh.castShadow = true; mesh.receiveShadow = true; mesh.frustumCulled = false;
  const depth = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
  depth.onBeforeCompile = sh => patchDepth(sh, U); depth.customProgramCacheKey = () => 'gaga-figure-depth';
  const distance = new THREE.MeshDistanceMaterial();
  distance.onBeforeCompile = sh => patchDepth(sh, U); distance.customProgramCacheKey = () => 'gaga-figure-distance';
  mesh.customDepthMaterial = depth; mesh.customDistanceMaterial = distance;
  object3d.add(mesh);
  mesh.bind(skeleton, new THREE.Matrix4());

  function applyMaterialUniforms() {
    U.grainAmp.value = current.def.grain; U.cavityStrength.value = current.def.cavity;
    U.glowColor.value.setRGB(0.92, 0.92, 0.9).multiplyScalar(GLOW_TONE[current.name] ?? 0.8);
    U.fabricColor.value.setHex(current.def.fabric); U.fabricSheen.value.setHex(current.def.fabricSheen); U.fabricRough.value = current.def.fabricRough;
    current.head.visible = headVisible;
  }
  applyMaterialUniforms();

  // ---------------- flesh springs (one per bone, world space, driven by bone acceleration)
  const flesh = { gain: 0.12, stiffness: 140, damping: 9 };
  const ref = allBones.map((b, i) => {
    const name = BODY_META.bones[i]; const src = i < bones.length ? BONES[i] : BONES[BONE_INDEX[BODY_META.helpers[i - bones.length].source]];
    return new THREE.Vector3(src.dir[0], src.dir[1], src.dir[2]).multiplyScalar(src.length * 0.5 * (name === 'root' ? 0 : 1));
  });
  const S = { off: new Float32Array(NF * 3), vel: new Float32Array(NF * 3), prev: new Float32Array(NF * 3), prevV: new Float32Array(NF * 3), acc: new Float32Array(NF * 3), init: false };
  const _v = new THREE.Vector3(), _m3 = new THREE.Matrix3(), _q = new THREE.Quaternion(), _qi = new THREE.Quaternion(), _tw = new THREE.Quaternion(), _sw = new THREE.Quaternion();
  let glowPoints = [];

  function updateHelpers() {
    for (const h of helpers) {
      const q = h.src.quaternion, d = h.def;
      h.bone.position.copy(h.src.position);
      if (d.mode === 'slerp') { h.bone.quaternion.slerpQuaternions(_qi.identity(), q, d.s); continue; }
      if (d.mode === 'glute') { // hip-flexion corrective: partial rotation plus flattening of the buttock toward the hip
        h.bone.quaternion.slerpQuaternions(_qi.identity(), q, d.s);
        const fa = Math.max(0, Math.min(1, _v.set(0, -1, 0).applyQuaternion(q).z));
        h.bone.scale.set(1, 1 - d.fy * fa, 1 - d.fz * fa);
        continue;
      }
      const a = h.axis, p = q.x * a.x + q.y * a.y + q.z * a.z;
      _tw.set(a.x * p, a.y * p, a.z * p, q.w);
      if (_tw.lengthSq() < 1e-10) _tw.identity(); else _tw.normalize();
      _sw.copy(q).multiply(_q.copy(_tw).invert());
      // slerpQuaternions copies its first argument into `this` first, so never pass the target as an input
      _q.slerpQuaternions(_qi.identity(), _sw, d.s);
      h.bone.quaternion.slerpQuaternions(_qi, _tw, d.t).premultiply(_q);
    }
  }

  function updateFlesh(dt) {
    const off = S.off, vel = S.vel;
    if (flesh.gain <= 0 || dt <= 0) {
      if (flesh.gain <= 0) { off.fill(0); vel.fill(0); }
    } else {
      const first = !S.init;
      for (let i = 0; i < NF; i++) {
        _v.copy(ref[i]).applyMatrix4(allBones[i].matrixWorld);
        const j = 3 * i;
        if (first) { S.prev[j] = _v.x; S.prev[j + 1] = _v.y; S.prev[j + 2] = _v.z; S.prevV[j] = S.prevV[j + 1] = S.prevV[j + 2] = 0; continue; }
        const vx = (_v.x - S.prev[j]) / dt, vy = (_v.y - S.prev[j + 1]) / dt, vz = (_v.z - S.prev[j + 2]) / dt;
        let ax = (vx - S.prevV[j]) / dt, ay = (vy - S.prevV[j + 1]) / dt, az = (vz - S.prevV[j + 2]) / dt;
        if (ax * ax + ay * ay + az * az > 400 * 400) ax = ay = az = 0; // teleport: ignore
        const lp = Math.min(1, dt * 25);
        S.acc[j] += (ax - S.acc[j]) * lp; S.acc[j + 1] += (ay - S.acc[j + 1]) * lp; S.acc[j + 2] += (az - S.acc[j + 2]) * lp;
        S.prev[j] = _v.x; S.prev[j + 1] = _v.y; S.prev[j + 2] = _v.z; S.prevV[j] = vx; S.prevV[j + 1] = vy; S.prevV[j + 2] = vz;
      }
      S.init = true;
      const steps = Math.max(1, Math.ceil(dt * 120)), h = dt / steps, K = flesh.stiffness, Cd = flesh.damping, G = flesh.gain;
      for (let s = 0; s < steps; s++) for (let j = 0; j < NF * 3; j++) {
        vel[j] += (-K * off[j] - Cd * vel[j] - G * S.acc[j]) * h;
        off[j] += vel[j] * h;
      }
      for (let i = 0; i < NF; i++) {
        const j = 3 * i, l = Math.hypot(off[j], off[j + 1], off[j + 2]);
        if (l > 0.012) { const k = (0.012 + 0.016 * Math.tanh((l - 0.012) / 0.016)) / l; off[j] *= k; off[j + 1] *= k; off[j + 2] *= k; } // soft limit, max 28 mm
      }
    }
    _m3.setFromMatrix4(mesh.matrixWorld).invert();
    const arr = U.fleshOffsets.value;
    for (let i = 0; i < NF; i++) arr[i].set(off[3 * i], off[3 * i + 1], off[3 * i + 2]).applyMatrix3(_m3);
  }

  // Glow points usually sit inside the body. Each is anchored to its nearest rest-pose surface vertex (cached), so
  // the spot lands on the skin above the point instead of fading out with depth or washing a whole limb.
  function updateGlow() {
    const n = Math.min(MAX_GLOW, glowPoints.length);
    for (let i = 0; i < n; i++) {
      const g = glowPoints[i], bn = byName[g.bone] ? g.bone : 'pelvis', b = byName[bn], o = g.offset || [0, 0, 0];
      const a = glowAnchor(bn, o);
      _v.set(a.offset[0], a.offset[1], a.offset[2]).applyMatrix4(b.matrixWorld);
      U.glowPos.value[i].set(_v.x, _v.y, _v.z, g.radius ?? 0.08);
      _v.set(o[0], o[1], o[2]).applyMatrix4(b.matrixWorld);
      U.glowIn.value[i].set(_v.x, _v.y, _v.z, a.depth);
      U.glowNrm.value[i].set(a.normal[0], a.normal[1], a.normal[2]).transformDirection(b.matrixWorld);
      U.glowInt.value[i] = Math.max(0, Math.min(1, g.intensity ?? 1));
    }
    U.glowCount.value = n;
  }

  const figure = {
    object3d, mesh, bones, byName, skeleton, role,
    debug: { uniforms: U, flesh },
    get materialName() { return current.name; },
    setMaterial(name) {
      if (!MATERIALS[name]) return;
      current = getSet(name); mesh.material = [current.body, current.head]; applyMaterialUniforms();
    },
    setFlesh({ gain, stiffness, damping } = {}) {
      if (gain !== undefined) flesh.gain = Math.max(0, gain);
      if (stiffness !== undefined) flesh.stiffness = Math.max(5, stiffness);
      if (damping !== undefined) flesh.damping = Math.max(0, damping);
    },
    setGlow(points) { glowPoints = Array.isArray(points) ? points.slice(0, MAX_GLOW) : []; },
    setHeadVisible(v) { headVisible = !!v; current.head.visible = headVisible; },
    setDancewear(on) { U.clothOn.value = on ? 1 : 0; }, // extra (not in CONTRACT): loose shorts + tank top zones, on by default
    update(dt) {
      dt = Math.min(Math.max(dt || 0, 0), 1 / 20);
      updateHelpers();
      object3d.updateMatrixWorld(true);
      updateFlesh(dt);
      updateGlow();
    },
    dispose() {
      for (const s of Object.values(sets)) { s.body.dispose(); s.head.dispose(); }
      depth.dispose(); distance.dispose(); skeleton.dispose();
      object3d.removeFromParent();
      if (--GEO_REFS <= 0 && GEO) { GEO.dispose(); GEO = null; GEO_REFS = 0; }
    },
  };
  figure.update(0);
  return figure;
}
